#!/usr/bin/env python3
# Step 2 of the zimrrl tutorial's organisational pass: merge the sections that covered the same topic twice.
#
#   python3 src/notes/scripts/zimrrl_tutorial_merge.py --dry-run DIR | --apply
#
# Runs on the page as step 1 (zimrrl_tutorial_reorganise.py) left it. Each merged section keeps the absorbed
# section's id as an extra anchor, so old links still land. Folds are dropped here and regenerated by zimrnum_ref.
import os
import re
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))))
ZRL_PAGE = os.path.join(ROOT, "src/notes/tutorials/zimrrl-tutorial.html")
ZN_PAGE = os.path.join(ROOT, "src/notes/tutorials/zimrnum-tutorial.html")

EPISODE_END = """<h3 id="truncation">3.3 How an episode ends: terminal and truncated<a class="anchor" href="#truncation">#</a></h3>
<a id="rl-truncation"></a>

<p>An episode stops for one of two reasons, and they are not the same reason.</p>

<pre><code class="zig">// The episode ended: the pole fell. No successor state exists.
const ended: zrl.Transition = .{ .reward = 1.0, .terminal = true };

// The episode was cut at a time limit. The world would have carried on.
const cut: zrl.Transition = .{ .reward = 1.0, .terminal = false, .truncated = true };</code></pre>

<p>A value function estimates the reward still to come. When an episode genuinely ends there is no future, so the
target is the reward alone. When it is cut at a time limit there <em>is</em> a future &mdash; the run simply stopped
observing it &mdash; so the target still includes the value of the state where it stopped. A truncated transition
bootstraps exactly like one in the middle of an episode: truncation changes where the trajectory stops, not what the
state it stopped at is worth.</p>

<p>A single <code>done</code> flag cannot express the difference, and conflating the two trains without failing.
Report a time limit as terminal and the bootstrap disappears at every horizon cut: the critic learns a cliff the
environment does not have, and the policy learns to act as though time is running out &mdash; because as far as the
value function is concerned, it is. Nothing crashes and the loss curve looks normal; the returns are simply lower than
they should be.</p>

<p>Off-policy, the rule lives in one place, and both <code>dqnTarget</code> and <code>sacTarget</code> ask it:</p>

<pre><code class="zig">pub fn bootstraps(self: Transition) bool {
    return !self.terminal;
}</code></pre>

<p><code>validate</code> refuses a transition that sets both flags. <code>terminal</code> comes from the environment and
<code>truncated</code> from the rollout loop's step counter, so a caller can set both without noticing, and
<code>terminal</code> would then quietly win.</p>

<p>On-policy, <a href="#gae"><code>RolloutStep</code></a> makes the same distinction with <code>terminal</code> &mdash;
there is no future here &mdash; and <code>episode_end</code> &mdash; do not carry the advantage trace past this step.
Every terminal step ends the trace; a truncation ends the trace without being terminal.
<code>RolloutBuffer.record</code> takes <code>terminal</code> and <code>truncated</code> and sets both fields, so neither
is derived by hand.</p>
"""

ROLLOUTS_AND_REPLAY = """<h3 id="rl-collect">4.1 Rollouts and replay<a class="anchor" href="#rl-collect">#</a></h3>
<a id="rlreplay"></a>

<p>The two families of methods store experience differently. An on-policy method records one rollout with the policy
it is about to update, learns from it, and discards it. An off-policy method keeps a ring of past transitions and
samples batches from it many times over.</p>

<pre><code class="zig">var rollout: zrl.RolloutBuffer = try zrl.RolloutBuffer.init(gpa, horizon);
defer rollout.deinit(gpa);

try rollout.record(reward, value, next_value, terminal, truncated, log_prob);

var adv: [horizon]f64 = undefined;
var ret: [horizon]f64 = undefined;
try rollout.advantages(cfg.gamma, cfg.lambda, &amp;adv, &amp;ret);</code></pre>

<p>A <strong>rollout</strong> buffer is not a ring. <a href="#gae">GAE</a> walks backwards through a contiguous stretch
of time, building each step's advantage from the one after it, so overwriting the start of a rollout while its end is
still being collected would corrupt every advantage that depends on it. <code>record</code> therefore refuses when the
buffer is full rather than wrapping, and <code>clear</code> starts the next rollout.</p>

<p>A <strong>replay</strong> buffer is a ring. <code>ReplayBuffer</code> stores fixed-width transitions and overwrites the
oldest once full: a transition gathered ten thousand steps ago says less about the current policy than a recent one,
and overwriting the oldest slot is the simplest schedule that forgets. A transition is a flat slice whose layout the
caller decides &mdash; the buffer does not interpret it, so one type serves discrete and continuous problems.
<code>sample</code> is addressable: the same <code>(rng, index)</code> yields the same batch.</p>

<p>A world model learns from windows of consecutive steps of one environment rather than from single transitions;
<a href="#wm-replay">SequenceReplay (9.9)</a> keeps one such ring per environment.</p>
"""

GAE = """<h3 id="gae">4.2 Advantages: GAE<a class="anchor" href="#gae">#</a></h3>
<a id="rlgae"></a>

<pre><code>try zrl.gae(steps, 0.99, 0.95, &amp;advantages, &amp;returns);</code></pre>

<p>A policy gradient needs to know whether an action did better than expected. The crude answer is the whole
discounted return: unbiased and extremely noisy. The other extreme is the one-step TD error: low variance, biased by
whatever the critic gets wrong.</p>

<p>GAE interpolates with <code>lambda</code>:</p>

<pre><code>lambda 0     the one-step TD error
lambda 0.5   between
lambda 1     the full discounted return</code></pre>

<p>0.95 is the usual choice and is not magic. <code>gamma</code> discounts the future as everywhere else.</p>

<h4>terminal stops the bootstrap; episode_end stops the trace</h4>

<p>Each step carries the two flags of <a href="#truncation">3.3</a>, and here they do two different jobs.</p>

<p><code>terminal</code> means the episode genuinely ended &mdash; the pole fell. There is no future to bootstrap from,
so the next state's value is <em>zero by definition</em>, not whatever the critic happens to predict about a state
that does not exist.</p>

<p><code>episode_end</code> means the rollout stopped here, terminal or not. What stops is the <em>trace</em>: an
advantage must not carry across a seam where the following reward belongs to a different trajectory.</p>

<pre><code>reward 1, value 1, next_value 99, gamma 1

terminal = true    ->  advantage 0     the 99 is ignored
terminal = false   ->  advantage 99    the 99 is used</code></pre>

<p>A truncation sets <code>episode_end</code> without <code>terminal</code>: the next state exists and its predicted
value is real, so the bootstrap stands, but the trace still stops. Using <code>terminal</code> for it throws away a
legitimate estimate and biases the critic low; using <code>episode_end</code> alone for a real termination bootstraps
off a state the agent never reached and biases it high.</p>

<h4>The recurrence runs backward</h4>

<pre><code>bootstrap    = &gamma; &middot; next_value[i] &middot; (1 &minus; terminal[i])
&delta;            = reward[i] + bootstrap &minus; value[i]
running      = &delta; + &gamma;&lambda; &middot; (1 &minus; episode_end[i]) &middot; running     // walked backwards
advantage[i] = running
return[i]    = running + value[i]</code></pre>

<p>Each advantage depends on the one after it, so a forward loop would need the answer before it had it. Walking back
from the end costs one pass and no extra storage. <code>gae</code> runs the recurrence over <code>RolloutStep</code>
values; <code>generalizedAdvantage</code> runs the same recurrence over separate arrays, with the flags as 0 or 1.</p>

<p><code>returns</code> comes out as the advantage plus the critic's own prediction. Fitting the critic against that
rather than the raw discounted return is what keeps the two halves consistent. With &lambda; = 1 and every value zero,
the recurrence reduces to the plain discounted return, which is what <code>discountedReturns</code> computes.</p>
"""

PPO_CLIP = """<h3 id="rl-ppo">6.1 PPO: what the clip is for<a class="anchor" href="#rl-ppo">#</a></h3>
<a id="rlppo"></a>

<p>The policy-gradient idea is simple: increase the probability of actions that did better than expected. The problem
is that a single large update can move the policy somewhere the collected data says nothing about &mdash; and that
data is all there is, because it came from the old policy.</p>

<p>PPO's answer is a <em>trust region</em>. It measures how much the policy changed as a ratio, and declines to
reward changes beyond a band:</p>

<pre><code class="zig">pub fn ppoClipSample(
    comptime T: type,
    log_prob_new: T,
    log_prob_old: T,
    advantage: T,
    clip: T,
) T {
    const ratio: T = @exp(log_prob_new - log_prob_old);
    const unclipped: T = ratio * advantage;
    const clipped: T = clamp(ratio, 1 - clip, 1 + clip) * advantage;
    return @min(unclipped, clipped);
}</code></pre>

<p>The <code>@min</code> is the whole algorithm. For a positive advantage the objective stops improving once the ratio
passes <code>1 + clip</code>; for a negative one, once it drops below <code>1 &minus; clip</code>. An update that pushes
the ratio far outside the band <em>in the improving direction</em> earns nothing extra, so there is no reward for
overshooting. A move in the wrong direction is never clipped away: a ratio of 5 with a negative advantage costs its
full price, so the gradient that corrects a bad step survives. Clipping both ways would remove it.</p>

<p>The function returns an objective to maximise; a gradient step descends its negation, which is what
<a href="#ppo">6.2</a> builds on the graph.</p>

<h4>Three orderings worth getting right</h4>

<p><strong>Normalise advantages once, over the whole rollout</strong> &mdash; not per minibatch. A minibatch of 32
estimates its own mean and spread from 32 samples, so the scale shifts between strides and the relative weighting
between them is lost.</p>

<p><strong>Shuffle per epoch.</strong> Each pass over the data should see a different partition, or the optimiser sees
the same grouping every time and the updates correlate.</p>

<p><strong>Weight statistics by minibatch size.</strong> Ten samples in strides of four is 4, 4 and a short 2.
Averaging three stride-means equally gives those last two samples a third of the reported <code>approx_kl</code>
instead of a fifth &mdash; and <code>approx_kl</code> is what an early-stopping rule reads.</p>
"""

MERGES = [  # (first id, the id where the replaced span ends, merged html)
    ("truncation", '<h2 id="experience">', EPISODE_END),
    ("rl-collect", '<h3 id="gae">', ROLLOUTS_AND_REPLAY),
    ("gae", '<h3 id="minibatchorder">', GAE),
    ("rl-ppo", '<h3 id="ppo">', PPO_CLIP),
]


def fail(message):
    print("zimrrl_tutorial_merge: " + message)
    sys.exit(1)


def main():
    if len(sys.argv) < 2 or sys.argv[1] not in ("--dry-run", "--apply"):
        fail("usage: --dry-run DIR | --apply")
    text = open(ZRL_PAGE).read()
    ids_before = set(re.findall(r'\bid="([\w-]+)"', text))
    for first, end_marker, merged in MERGES:
        start = text.index(f'<h3 id="{first}">')
        end = text.index(end_marker, start)
        text = text[:start] + merged + "\n" + text[end:]

    # Renumber every numbered h3 under its chapter, then regenerate the contents list.
    out, chapter, sub = [], 0, 0
    for line in text.split("\n"):
        h2 = re.match(r'^<h2 id="[\w-]+">(\d+)\. ', line)
        h3 = re.match(r'^(<h3 id="[\w-]+">)(\d+)\.(\d+) ', line)
        if h2:
            chapter, sub = int(h2.group(1)), 0
        elif h3:
            sub += 1
            line = f"{h3.group(1)}{chapter}.{sub} " + line[h3.end():]
        out.append(line)
    text = "\n".join(out)
    contents = re.findall(r'^<h([23]) id="([\w-]+)">(.*?)<a class', text, re.M)
    nav = ["<nav>", "<strong>Contents</strong>", "<ol>"]
    for index, (level, anchor, title) in enumerate(contents):
        if level != "2":
            continue
        children = []
        for level2, anchor2, title2 in contents[index + 1:]:
            if level2 == "2":
                break
            children.append(f'<li><a href="#{anchor2}">{re.sub(r"^[0-9.]+ ", "", title2)}</a></li>')
        title = re.sub(r'^\d+\.\s+', '', title)
        if children:
            nav += [f'  <li><a href="#{anchor}">{title}</a>', "    <ol>" + "\n        ".join(children) + "</ol></li>"]
        else:
            nav.append(f'  <li><a href="#{anchor}">{title}</a></li>')
    nav += ["</ol>", "</nav>"]
    text = re.sub(r'<nav>.*?</nav>', "\n".join(nav), text, count=1, flags=re.S)

    ids_after = set(re.findall(r'\bid="([\w-]+)"', text))
    if ids_before - ids_after:
        fail(f"ids lost: {sorted(ids_before - ids_after)}")
    dangling = sorted({a for a in re.findall(r'href="#([\w-]+)"', text) if a not in ids_after})
    if dangling:
        fail(f"links to ids that do not exist: {dangling}")
    number = re.search(r'<h3 id="minibatchorder">(\d+\.\d+) ', text).group(1)
    zn = open(ZN_PAGE).read()
    old = '<a href="zimrrl-tutorial.html#minibatchorder">4.5 in the zimrrl tutorial</a>'
    if zn.count(old) != 1:
        fail("zimrnum's minibatchorder pointer not found")
    zn = zn.replace(old, f'<a href="zimrrl-tutorial.html#minibatchorder">{number} in the zimrrl tutorial</a>')
    print(f"merged {len(MERGES)} pairs; minibatchorder is now {number}; zimrrl page {text.count(chr(10)) + 1} lines")
    if sys.argv[1] == "--dry-run":
        os.makedirs(sys.argv[2], exist_ok=True)
        open(os.path.join(sys.argv[2], "zimrrl-tutorial.html"), "w").write(text)
        open(os.path.join(sys.argv[2], "zimrnum-tutorial.html"), "w").write(zn)
        print(f"dry run written to {sys.argv[2]}")
    else:
        open(ZRL_PAGE, "w").write(text)
        open(ZN_PAGE, "w").write(zn)
        print("applied")


main()
